// Code Node - Processar Callback com Quick Edit (ATUALIZADO)
const update = $json;
const callbackQuery = update.callback_query;
const callbackData = callbackQuery.data;
const userId = callbackQuery.from.id;
const userFullName = `${callbackQuery.from.first_name} ${callbackQuery.from.last_name || ''}`.trim();
const messageId = callbackQuery.message.message_id;
const chatId = callbackQuery.message.chat.id;

// Timestamp atual
const now = new Date();
const nowISO = now.toISOString();
const dataBrasil = now.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const horaBrasil = now.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// Parseia a acao - suporta formato simples (action_postid) e quick edit (qe_action_postid)
const parts = callbackData.split('_');
let action, postId;

if (parts[0] === 'qe') {
  // Quick edit callback: qe_action_postid
  action = 'qe_' + parts[1]; // qe_title, qe_content, qe_tags, qe_confirm, qe_redo, qe_cancel
  postId = parts.slice(2).join('_');
} else {
  // Callback normal: action_postid
  action = parts[0];
  postId = parts.slice(1).join('_');
}

// Define o novo status baseado na acao
let newStatus, statusEmoji, actionMessage, reviewNotes;
let needsFeedback = false;
let needsQuickEdit = false;
let quickEditType = null;

switch(action) {
  case 'approve':
    newStatus = 'approved';
    statusEmoji = '✅';
    actionMessage = 'APROVADO';
    reviewNotes = `Aprovado por ${userFullName} via Telegram em ${dataBrasil} às ${horaBrasil}`;
    break;

  case 'edit':
    // NOVO: Mostrar menu de edicao rapida
    return {
      is_quick_edit_menu: true,
      callback_query_id: callbackQuery.id,
      post_id: postId,
      chat_id: chatId,
      message_id: messageId,
      user_id: userId,
      user_name: userFullName,
      answer_callback: {
        text: '✏️ Selecione o que editar',
        show_alert: false
      },
      edit_menu: {
        chat_id: chatId,
        text: '✏️ *EDIÇÃO RÁPIDA*\n━━━━━━━━━━━━━━━━━━━━━\n\n📝 O que você deseja editar?\n\n_Selecione uma opção abaixo:_',
        parse_mode: 'Markdown',
        reply_markup: JSON.stringify({
          inline_keyboard: [
            [
              { text: '📝 Título', callback_data: `qe_title_${postId}` },
              { text: '🏷️ Tags', callback_data: `qe_tags_${postId}` }
            ],
            [
              { text: '📄 Conteúdo (AI)', callback_data: `qe_content_${postId}` }
            ],
            [
              { text: '❌ Cancelar', callback_data: `qe_cancel_${postId}` }
            ]
          ]
        })
      }
    };

  case 'qe_title':
  case 'qe_tags':
  case 'qe_content':
    needsQuickEdit = true;
    quickEditType = action.replace('qe_', '');
    break;

  case 'qe_confirm':
    return {
      is_quick_edit_confirm: true,
      callback_query_id: callbackQuery.id,
      post_id: postId,
      chat_id: chatId,
      message_id: messageId,
      user_id: userId,
      user_name: userFullName,
      answer_callback: {
        text: '⏳ Aplicando alterações...',
        show_alert: false
      }
    };

  case 'qe_redo':
    return {
      is_quick_edit_redo: true,
      callback_query_id: callbackQuery.id,
      post_id: postId,
      chat_id: chatId,
      message_id: messageId,
      user_id: userId,
      user_name: userFullName,
      answer_callback: {
        text: '🔄 Digite novamente',
        show_alert: false
      }
    };

  case 'qe_cancel':
    return {
      is_quick_edit_cancel: true,
      callback_query_id: callbackQuery.id,
      post_id: postId,
      chat_id: chatId,
      message_id: messageId,
      user_id: userId,
      user_name: userFullName,
      answer_callback: {
        text: '❌ Edição cancelada',
        show_alert: false
      }
    };

  case 'revise':
    newStatus = 'pending_feedback';
    statusEmoji = '✏️';
    actionMessage = 'AGUARDANDO REVISÕES';
    needsFeedback = true;
    break;

  case 'reject':
    newStatus = 'rejected';
    statusEmoji = '❌';
    actionMessage = 'REJEITADO';
    reviewNotes = `Rejeitado por ${userFullName} via Telegram em ${dataBrasil} às ${horaBrasil}`;
    break;

  case 'skip':
    newStatus = 'draft';
    statusEmoji = '⏭️';
    actionMessage = 'PULADO';
    reviewNotes = `Pulado para revisão posterior por ${userFullName} em ${dataBrasil} às ${horaBrasil}`;
    break;

  case 'schedule':
    newStatus = 'scheduled';
    statusEmoji = '📅';
    actionMessage = 'AGENDADO';
    reviewNotes = `Agendado por ${userFullName} via Telegram em ${dataBrasil} às ${horaBrasil}`;
    break;

  default:
    console.log('Ação não reconhecida:', action);
    newStatus = 'draft';
    statusEmoji = '⚠️';
    actionMessage = 'AÇÃO DESCONHECIDA';
    reviewNotes = `Ação '${action}' não reconhecida em ${dataBrasil} às ${horaBrasil}`;
}

// Se precisa quick edit, prepara sessao
if (needsQuickEdit) {
  const editSessionId = `edit_${postId.substring(0, 8)}_${Date.now()}`;

  let promptText, fieldLabel;
  switch(quickEditType) {
    case 'title':
      promptText = '📝 *EDITAR TÍTULO*\n\nEnvie o novo título do post:\n\n_Regras: 10-120 caracteres_';
      fieldLabel = 'Título';
      break;
    case 'tags':
      promptText = '🏷️ *EDITAR TAGS*\n\nEnvie as novas tags separadas por vírgula:\n\n_Exemplo: minério, china, vale, commodities_\n_Regras: 1-10 tags, cada uma com 2-30 caracteres_';
      fieldLabel = 'Tags';
      break;
    case 'content':
      promptText = '📄 *EDITAR CONTEÚDO*\n\nDescreva as alterações que deseja no conteúdo:\n\n_As alterações serão processadas por AI_\n_Regras: mínimo 20 caracteres_';
      fieldLabel = 'Conteúdo';
      break;
  }

  return {
    is_quick_edit_start: true,
    callback_query_id: callbackQuery.id,
    post_id: postId,
    chat_id: chatId,
    message_id: messageId,
    user_id: userId,
    user_name: userFullName,
    edit_type: quickEditType,
    field_label: fieldLabel,
    edit_session: {
      session_id: editSessionId,
      post_id: postId,
      chat_id: String(chatId),
      user_id: String(userId),
      message_id: messageId,
      edit_type: quickEditType,
      stage: 'waiting_input',
      expires_at: new Date(Date.now() + 10 * 60000).toISOString()
    },
    answer_callback: {
      text: `✏️ Editando ${fieldLabel.toLowerCase()}`,
      show_alert: false
    },
    prompt_message: {
      chat_id: chatId,
      text: promptText,
      parse_mode: 'Markdown'
    }
  };
}

// Se precisa feedback antigo (revisao com AI)
if (needsFeedback) {
  const feedbackSessionId = `feedback_${postId.substring(0, 8)}_${Date.now()}`;
  const messageCaption = callbackQuery.message.caption || '';
  const messageText = callbackQuery.message.text || messageCaption;
  const messageLines = messageText.split('\n');
  let postTitle = 'Post';

  for (let i = 0; i < messageLines.length; i++) {
    const line = messageLines[i].trim();
    if (line.startsWith('*') && line.length > 10 && !line.includes('POST')) {
      postTitle = line.replace(/\*/g, '').trim();
      break;
    }
  }

  return {
    needs_feedback: true,
    stop_flow: true,
    callback_query_id: callbackQuery.id,
    feedback_session: {
      session_id: feedbackSessionId,
      post_id: postId,
      chat_id: chatId,
      user_id: userId,
      message_id: messageId,
      status: 'waiting',
      expires_at: new Date(Date.now() + 5 * 60000).toISOString()
    },
    telegram_response: {
      callback_query_id: callbackQuery.id,
      text: '✏️ Modo revisão ativado',
      show_alert: false
    },
    edit_message: {
      chat_id: chatId,
      message_id: messageId,
      text: `✏️ *AGUARDANDO SUAS REVISÕES*\n\n📝 Post: ${postTitle.substring(0, 50)}...\n\n_Digite as alterações necessárias na próxima mensagem..._\n\n⏰ Timeout: 5 minutos\n\n_ID: ${postId.substring(0, 8)}_`,
      parse_mode: 'Markdown'
    },
    feedback_prompt: {
      chat_id: chatId,
      text: '✏️ *O que precisa ajustar?*\n\n_Digite suas observações:_',
      parse_mode: 'Markdown'
    }
  };
}

// Retorno normal para outras acoes
return {
  needs_feedback: false,
  callback_query_id: callbackQuery.id,
  update_data: {
    post_id: postId,
    new_status: newStatus,
    reviewed_by: userFullName,
    reviewed_at: nowISO,
    review_notes: reviewNotes || null
  },
  answer_callback: {
    callback_query_id: callbackQuery.id,
    text: `${statusEmoji} ${actionMessage}!`,
    show_alert: false
  },
  edit_message: {
    chat_id: chatId,
    message_id: messageId,
    text: `${statusEmoji} *POST ${actionMessage}*\n\n*Revisado por:* ${userFullName}\n*Data:* ${dataBrasil}\n*Horário:* ${horaBrasil}\n\nID: ${postId.substring(0, 8)}`,
    parse_mode: 'Markdown'
  }
};

// Code Node - Preparar Post HTML + Payload Telegram (sendDocument)
// Replica a lógica do Workflow 3 para posts subsequentes

const draft = $json;

// Validação rápida
if (!draft || !draft.id) {
  throw new Error('Próximo post não possui dados válidos');
}

// Variáveis de controle da sessão
const currentNumber = draft.review_order || 1;
const totalPosts = draft.total_in_session || 1;

// Define o chat_id
const chatId = "8375309778";

// Configuração de tier com cores para o HTML
let tierEmoji, tierLabel, tierColor;
switch(draft.tier) {
  case 'TIER_1':
    tierEmoji = '🔴';
    tierLabel = 'CRÍTICO - Revisão Urgente';
    tierColor = '#dc3545'; // vermelho
    break;
  case 'TIER_2':
    tierEmoji = '🟡';
    tierLabel = 'Normal - Revisão Regular';
    tierColor = '#ffc107'; // amarelo
    break;
  case 'TIER_3':
    tierEmoji = '🟢';
    tierLabel = 'Baixa Prioridade';
    tierColor = '#28a745'; // verde
    break;
  default:
    tierEmoji = '⚪';
    tierLabel = 'Sem Classificação';
    tierColor = '#6c757d'; // cinza
}

// Formata a data
const createdDate = draft.created_at 
  ? new Date(draft.created_at).toLocaleDateString('pt-BR', {
      day: '2-digit',
      month: '2-digit', 
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  : 'Data não disponível';

const originalDate = draft.original_date
  ? new Date(draft.original_date).toLocaleDateString('pt-BR')
  : null;

// Formata categorias e tags
const categories = Array.isArray(draft.categories) 
  ? draft.categories.join(', ') 
  : (draft.categories || 'Sem categorias');

const tags = Array.isArray(draft.tags) 
  ? draft.tags.join(', ') 
  : (draft.tags || '');

// Conteúdo do post (prefere HTML, fallback para Markdown)
const postContent = draft.content_html || draft.content_markdown || 'Conteúdo não disponível';

// ============================================
// TEMPLATE HTML COMPLETO E PROFISSIONAL
// ============================================
const htmlContent = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${draft.title || 'Post para Revisão'}</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
      line-height: 1.6;
      color: #333;
      background: #f5f5f5;
      padding: 16px;
    }

    .container {
      max-width: 800px;
      margin: 0 auto;
      background: white;
      border-radius: 12px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.1);
      overflow: hidden;
    }

    .header {
      background: ${tierColor};
      color: white;
      padding: 20px;
    }

    .header-badge {
      display: inline-block;
      background: rgba(255,255,255,0.2);
      padding: 4px 12px;
      border-radius: 20px;
      font-size: 14px;
      margin-bottom: 12px;
    }

    .header h1 {
      font-size: 22px;
      font-weight: 600;
      line-height: 1.3;
    }

    .meta-section {
      background: #f8f9fa;
      padding: 16px 20px;
      border-bottom: 1px solid #e9ecef;
    }

    .meta-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 12px;
    }

    .meta-item {
      font-size: 14px;
    }

    .meta-label {
      color: #666;
      font-size: 12px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .meta-value {
      font-weight: 500;
      color: #333;
    }

    .categories {
      padding: 12px 20px;
      background: #fff;
      border-bottom: 1px solid #e9ecef;
    }

    .category-tag {
      display: inline-block;
      background: #e9ecef;
      color: #495057;
      padding: 4px 10px;
      border-radius: 4px;
      font-size: 13px;
      margin: 2px 4px 2px 0;
    }

    .excerpt {
      padding: 20px;
      background: #fffbeb;
      border-left: 4px solid #f59e0b;
      margin: 20px;
      border-radius: 0 8px 8px 0;
    }

    .excerpt-label {
      font-size: 12px;
      text-transform: uppercase;
      color: #92400e;
      margin-bottom: 8px;
      font-weight: 600;
    }

    .excerpt-text {
      color: #78350f;
      font-style: italic;
    }

    .content {
      padding: 24px 20px;
    }

    .content-label {
      font-size: 12px;
      text-transform: uppercase;
      color: #666;
      margin-bottom: 16px;
      font-weight: 600;
      letter-spacing: 0.5px;
    }

    .content-body {
      font-size: 16px;
      line-height: 1.8;
    }

    .content-body h1, .content-body h2, .content-body h3 {
      margin-top: 24px;
      margin-bottom: 12px;
      color: #1a1a1a;
    }

    .content-body h2 {
      font-size: 20px;
      border-bottom: 2px solid #e9ecef;
      padding-bottom: 8px;
    }

    .content-body h3 {
      font-size: 17px;
    }

    .content-body p {
      margin-bottom: 16px;
    }

    .content-body ul, .content-body ol {
      margin: 16px 0;
      padding-left: 24px;
    }

    .content-body li {
      margin-bottom: 8px;
    }

    .content-body strong {
      color: #1a1a1a;
    }

    .footer {
      background: #f8f9fa;
      padding: 16px 20px;
      font-size: 12px;
      color: #666;
      text-align: center;
      border-top: 1px solid #e9ecef;
    }

    .footer-id {
      font-family: monospace;
      background: #e9ecef;
      padding: 2px 8px;
      border-radius: 4px;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div class="header-badge">${tierEmoji} ${tierLabel}</div>
      <h1>${draft.title || 'Título não disponível'}</h1>
    </div>

    <div class="meta-section">
      <div class="meta-grid">
        <div class="meta-item">
          <div class="meta-label">Palavras</div>
          <div class="meta-value">${draft.word_count || 0}</div>
        </div>
        <div class="meta-item">
          <div class="meta-label">Tempo de Leitura</div>
          <div class="meta-value">${draft.reading_time_minutes || 1} min</div>
        </div>
        <div class="meta-item">
          <div class="meta-label">Data Original</div>
          <div class="meta-value">${originalDate || createdDate}</div>
        </div>
        <div class="meta-item">
          <div class="meta-label">Criado em</div>
          <div class="meta-value">${createdDate}</div>
        </div>
      </div>
    </div>

    <div class="categories">
      <span class="meta-label">Categorias: </span>
      ${(Array.isArray(draft.categories) ? draft.categories : [categories])
        .map(cat => `<span class="category-tag">${cat}</span>`).join('')}
      ${tags ? `<br><span class="meta-label" style="margin-top:8px;display:inline-block;">Tags: </span>
      ${(Array.isArray(draft.tags) ? draft.tags : tags.split(','))
        .map(tag => `<span class="category-tag">${tag.trim()}</span>`).join('')}` : ''}
    </div>

    ${draft.excerpt ? `
    <div class="excerpt">
      <div class="excerpt-label">📋 Resumo / Excerpt</div>
      <div class="excerpt-text">${draft.excerpt}</div>
    </div>
    ` : ''}

    <div class="content">
      <div class="content-label">📄 Conteúdo Completo</div>
      <div class="content-body">
        ${postContent}
      </div>
    </div>

    <div class="footer">
      Post ID: <span class="footer-id">${draft.id || 'N/A'}</span>
      ${draft.slug ? ` | Slug: <span class="footer-id">${draft.slug}</span>` : ''}
    </div>
  </div>
</body>
</html>`;

// ============================================
// CAPTION PARA O TELEGRAM (resumido)
// ============================================
const caption = `📝 *POST ${currentNumber}/${totalPosts}*  |  ${tierEmoji} *${draft.tier || 'N/A'}*

*${draft.title || 'Sem título'}*

📊 ${draft.word_count || 0} palavras  •  ⏱ ${draft.reading_time_minutes || 1} min
📁 ${categories}

💡 _Abra o arquivo HTML para revisar o conteúdo completo_`;

// ============================================
// BOTÕES INLINE
// ============================================
const inlineKeyboard = [
  [
    { text: '✅ Aprovar', callback_data: `approve_${draft.id}` },
    { text: '📅 Agendar', callback_data: `schedule_${draft.id}` }
  ],
  [
    { text: '✏️ Editar', callback_data: `edit_${draft.id}` },
    { text: '❌ Rejeitar', callback_data: `reject_${draft.id}` }
  ],
  [
    { text: '⏭️ Próximo', callback_data: `skip_${draft.id}` }
  ]
];

// ============================================
// GERA O ARQUIVO COMO BINARY
// ============================================
const fileName = `post_${draft.tier || 'draft'}_${(draft.id || 'unknown').substring(0, 8)}.html`;

// Converte o HTML para Buffer (binary)
const binaryData = Buffer.from(htmlContent, 'utf-8');

// ============================================
// RETORNA DADOS + BINARY PARA O HTTP REQUEST
// ============================================
return {
  json: {
    chat_id: chatId,
    caption: caption,
    parse_mode: "Markdown",
    reply_markup: JSON.stringify({
      inline_keyboard: inlineKeyboard
    }),
    // Dados extras para tracking
    draft_id: draft.id,
    draft_title: draft.title,
    file_name: fileName
  },
  binary: {
    document: {
      data: binaryData.toString('base64'),
      mimeType: 'text/html',
      fileName: fileName
    }
  }
};

// Code Node - Extrair Message ID da Resposta do Telegram

const telegramResponse = $json;

if (!telegramResponse.ok || !telegramResponse.result) {
  throw new Error('Resposta do Telegram inválida: ' + JSON.stringify(telegramResponse));
}

const messageId = telegramResponse.result.message_id;

// Pega o draft_id do Code Node que preparou o payload
const draftId = $('PREPARAR TELEGRAM').item.json.draft_id;

if (!draftId) {
  throw new Error('draft_id não encontrado no node anterior');
}

const sentAt = new Date().toISOString();

return {
  post_id: draftId,
  telegram_message_id: messageId,
  review_started_at: sentAt
};

// Code Node - Preparar Resumo Final da Sessão

// Busca informações da sessão que acabou de ser concluída
// USA MONTAR CAMPOS pois SALVAR STATUS não retorna os dados
const currentPost = $('MONTAR CAMPOS').first().json;
const sessionId = currentPost.review_session_id || 'sessao_desconhecida';
const totalPosts = currentPost.total_in_session || 1;

const chatId = "8375309778";

// Mensagem de conclusão celebratória
const messageText = `🎉 *REVISÃO CONCLUÍDA!*
━━━━━━━━━━━━━━━━━━━━━

Você finalizou a revisão de *${totalPosts} ${totalPosts === 1 ? 'post' : 'posts'}*!

📊 *Próximos passos:*
- Posts aprovados serão publicados automaticamente
- Posts para revisão aguardam seus ajustes
- Posts agendados serão publicados nas datas definidas
- Posts rejeitados foram arquivados

✨ *Excelente trabalho!*

━━━━━━━━━━━━━━━━━━━━━
_Sessão: ${sessionId.substring(0, 25)}..._
_Concluída em: ${new Date().toLocaleString('pt-BR')}_`;

const telegramPayload = {
  chat_id: chatId,
  text: messageText,
  parse_mode: "Markdown"
};

return {
  telegram_payload: telegramPayload,
  session_id: sessionId,
  total_posts: totalPosts,
  completed_at: new Date().toISOString()
};

// Code Node - Preparar Dados Completos
// Agora temos acesso ao post completo do banco com session_id correto

// Dados do callback (do primeiro Code Node)
const callbackData = $('PROCESSAR CALLBACK').item.json;
const action = callbackData.update_data?.new_status ? null : callbackData.update_data;
const userFullName = callbackData.update_data?.reviewed_by || 'Usuário';
const messageId = callbackData.edit_message?.message_id;
const chatId = callbackData.edit_message?.chat_id;
const callbackQueryId = callbackData.callback_query_id;

// Dados do post do banco (do Supabase Select)
const post = $json;
const postId = post.id;
const postTitle = post.title;
const sessionId = post.review_session_id;

// Timestamp formatado
const now = new Date();
const nowISO = now.toISOString();
const dataBrasil = now.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const horaBrasil = now.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// Pega dados já processados do PROCESSAR CALLBACK
const updateData = callbackData.update_data || {};
const answerCallback = callbackData.answer_callback || {};
const editMessage = callbackData.edit_message || {};

// Atualiza edit_message com dados do banco
editMessage.text = editMessage.text || `Post processado: ${postTitle}`;

return {
  update_data: {
    ...updateData,
    post_id: postId
  },
  answer_callback: answerCallback,
